}

.arrow-btn {
    width: 18px;
    height: 18px;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    border-radius: 50%;
    transition: transform 0.1s;
    -webkit-tap-highlight-color: transparent;
    flex-shrink: 0;
    transform-style: flat;
}

.arrow-btn svg {
    display: block;
    width: 100%;
    height: 100%;
}

.arrow-btn:active {
    transform: scale(0.8);
}

/*⁣⁠⁠⁠‍‍⁠‌‌⁠‍⁠⁠​‍​⁠​⁠⁠‌‌‌‌​‌‍⁠⁠⁠‌‍‍‌‌​‌‍‌⁠​‍⁠‌​‍​⁠‌⁠‌​‍​‍⁠‍‌​‍⁠‌‌⁠​⁣ ⭐ 核心：3D 透视容器 */
.carousel-container {
    flex: 1;
    height: 100%; 
    clip-path: url(#concave-scroll);
    overflow: hidden; 
    perspective: 800px; 
    transform-style: preserve-3d; 
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent; 
    box-shadow: 0 4px 15px rgba(0,0,0,0.1); 
}

.img-item {
    height: 100%;
    position: relative;
    overflow: hidden;
    border-left: 1px solid rgba(255, 255, 255, 0.6);
    border-right: 1px solid rgba(255, 255, 255, 0.6);
    background: rgba(0, 0, 0, 0.05); 
    transform-style: preserve-3d;
    transition: transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), 
                opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.img-item img {
    width: 100%;
    height: 100%;
    object-fit: cover; 
    display: block;
    will-change: transform, opacity;
    backface-visibility: hidden; 
}

/* ⭐ 3D 空间基础布局：中间小向后推，两边大向前推 */
.img-item.center {
    flex: 1.4; 
    z-index: 2;
    transform: translateZ(-40px) scale(0.85); 
}

.img-item.side.left {
    flex: 1.3; 
    transform-origin: right center; 
    transform: rotateY(28deg) translateZ(20px) scale(1.05); 
}

.img-item.side.right {
    flex: 1.3; 
    transform-origin: left center; 
    transform: rotateY(-28deg) translateZ(20px) scale(1.05); 
}

/* 垂直分割线 */
.img-item.center::before,
.img-item.center::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 0.5px;
    background: rgba(0,0,0,0.15);
    z-index: 3;
}
.img-item.center::before { left: 0; }
.img-item.center::after { right: 0; }

/* ================= ⭐ 底部动态波形区域（增加颜色变量） ================= */
.waveform-container {
    display: flex;
    align-items: flex-end; 
    justify-content: center;
    gap: 1.5px; 
    height: 28px; 
    width: 100%;
    margin-top: -18px; 
    z-index: 10; 
    flex-shrink: 0; 
}

.wave-bar {
    width: 2px; 
    /* ⭐ 核心修改：优先使用 waveColor 变量，如果没有则用当前字体颜色 */
    background-color: var(--wave-color, currentColor); 
    border-radius: 1px;
    height: 4px; 
    animation: wave 2s ease-in-out infinite;
}

/* 25条波浪线错落的延迟 */
.wave-bar:nth-child(1) { animation-delay: 0.0s; }
.wave-bar:nth-child(2) { animation-delay: 0.2s; }
.wave-bar:nth-child(3) { animation-delay: 0.4s; }
.wave-bar:nth-child(4) { animation-delay: 0.6s; }
.wave-bar:nth-child(5) { animation-delay: 0.8s; }
.wave-bar:nth-child(6) { animation-delay: 0.3s; }
.wave-bar:nth-child(7) { animation-delay: 0.5s; }
.wave-bar:nth-child(8) { animation-delay: 0.7s; }
.wave-bar:nth-child(9) { animation-delay: 0.9s; }
.wave-bar:nth-child(10) { animation-delay: 0.1s; }
.wave-bar:nth-child(11) { animation-delay: 0.4s; }
.wave-bar:nth-child(12) { animation-delay: 0.6s; }
.wave-bar:nth-child(13) { animation-delay: 0.8s; }
.wave-bar:nth-child(14) { animation-delay: 0.2s; }
.wave-bar:nth-child(15) { animation-delay: 0.5s; }
.wave-bar:nth-child(16) { animation-delay: 0.7s; }
.wave-bar:nth-child(17) { animation-delay: 0.9s; }
.wave-bar:nth-child(18) { animation-delay: 0.1s; }
.wave-bar:nth-child(19) { animation-delay: 0.3s; }
.wave-bar:nth-child(20) { animation-delay: 0.6s; }
.wave-bar:nth-child(21) { animation-delay: 0.8s; }
.wave-bar:nth-child(22) { animation-delay: 0.2s; }
.wave-bar:nth-child(23) { animation-delay: 0.4s; }
.wave-bar:nth-child(24) { animation-delay: 0.6s; }
.wave-bar:nth-child(25) { animation-delay: 0.8s; }

@keyframes wave {
    0%, 100% { height: 4px; }
    50% { height: var(--h, 14px); } 
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    background: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.widget-container {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    background: transparent;
    padding: 2px;
    overflow: hidden;
}

/*⁣⁠⁠⁠‍‍⁠‌‌⁠‍⁠⁠​‍​⁠​⁠⁠‌‌‌‌​‌‍⁠⁠⁠‌‍‍‌‌​‌‍‌⁠​‍⁠‌​‍​⁠‌⁠‌​‍​‍⁠‍‌​‍⁠‌‌⁠​⁣ ================= 1. 3D 封面轮播区域 ================= */
.cover-flow {
    position: relative;
    width: 100%;
    height: 100px; 
    display: flex;
    justify-content: center;
    align-items: center;
    perspective: 400px; 
    margin-bottom: 6px; 
}

.cover-card {
    position: absolute;
    width: 80px;
    height: 80px;
    border-radius: 6px;
    overflow: hidden;
    background: #eee;
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
    transition: transform 0.8s ease-in-out, opacity 0.8s ease-in-out;
    top: 50%;
    left: 50%;
    margin-top: -40px;
    margin-left: -40px;
}

.cover-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

/* ================= 2. 底部胶囊控制栏 ================= */
.control-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #ffffff; 
    color: #333333; /* 默认颜色，JS 会动态覆盖整个 color 属性 */
    border-radius: 20px;
    padding: 2px 8px; 
    width: 95%; 
    height: 26px; 
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    -webkit-tap-highlight-color: transparent; 
    box-sizing: border-box;
    z-index: 10; 
}

.btn {
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 8px; 
    font-weight: bold;
    color: inherit; /* 继承控制栏的动态颜色 */
    cursor: pointer;
    padding: 2px 4px; 
    border-radius: 4px; 
    transition: transform 0.1s, background-color 0.1s;
    user-select: none;
    flex-shrink: 0; 
}

.btn svg {
    display: block;
    stroke: currentColor; /* 跟随动态颜色 */
}

.btn:active {
    transform: scale(0.8); 
    background-color: rgba(128, 128, 128, 0.2); 
}

/* ================= 3. 进度条 ================= */
.progress-container {
    flex: 1; 
    margin: 0 4px;
    height: 16px; 
    display: flex;
    align-items: center;
    cursor: pointer;
    touch-action: none; 
}

.progress-bar {
    width: 100%;
    height: 3px;
    background: rgba(128, 128, 128, 0.3); /* 半透明轨道，黑白底都能看清 */
    border-radius: 2px;
    position: relative;
    overflow: visible; 
}

.progress-fill {
    width: 45%; 
    height: 100%;
    background: #111; /* JS会动态覆盖 */
    border-radius: 2px;
    position: absolute;
    top: 0;
    left: 0;
}

.progress-dot {
    position: absolute;
    top: 50%;
    left: 45%;
    width: 8px; 
    height: 8px;
    background: #111; /* JS会动态覆盖 */
    border-radius: 50%;
    transform: translate(-50%, -50%);
    box-shadow: 0 0 4px rgba(0,0,0,0.2);
    transition: transform 0.1s;
    z-index: 2;
}

.progress-container:active .progress-dot {
    transform: translate(-50%, -50%) scale(1.3);
}

/* ================= ⭐ 4. 音量弹层（保持白底独立） ================= */
.volume-popover {
    position: absolute;
    bottom: 36px;
    right: 35px; 
    background: #ffffff;
    padding: 8px 12px;
    border-radius: 16px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.15);

    display: flex;
    align-items: center;
    gap: 6px;

    opacity: 0;
    visibility: hidden;
    transform: translateY(10px);
    transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
    z-index: 5;
}

.volume-popover.show {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.vol-icon {
    color: #999;
    flex-shrink: 0;
}

.volume-slider {
    -webkit-appearance: none;
    appearance: none;
    width: 70px;
    height: 3px;
    background: #e0e0e0;
    border-radius: 2px;
    outline: none;
    cursor: pointer;
}

.volume-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 11px;
    height: 11px;
    background: #333;
    border-radius: 50%;
    cursor: pointer;
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
    transition: transform 0.1s;
}

.volume-slider::-webkit-slider-thumb:active {
    transform: scale(1.2);
}

.volume-slider::-moz-range-thumb {
    width: 11px;
    height: 11px;
    background: #333;
    border-radius: 50%;
    cursor: pointer;
    border: none;
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}

