  overflow: hidden;
}

/*⁣⁠⁠⁠‍‍⁠‌‌⁠‍⁠⁠​‍​⁠​⁠⁠‌‌‌‌​‌‍⁠⁠⁠‌‍‍‌‌​‌‍‌⁠​‍⁠‌​‍​⁠‌⁠‌​‍​‍⁠‍‌​‍⁠‌‌⁠​⁣ 3D 場景容器 */
.scene {
  /* 預設變數，JS 載入前會顯示這個顏色 plz */
  --line-color: #1e3c96; 
  --line-color-rgb: 30, 60, 150;

  width: 100%;
  height: 100%;
  position: relative;
  perspective: 800px;
  perspective-origin: 85% 50%; 
  display: flex;
  align-items: center;


  -webkit-mask-image: linear-gradient(to right, transparent 0%, transparent 3%, black 10%, black 100%);
  mask-image: linear-gradient(to right, transparent 0%, transparent 3%, black 10%, black 100%);
}

/* 放射狀透視線 d */
.perspective-lines {
  position: absolute;
  width: 100%;
  height: 100%;
  background: repeating-conic-gradient(
    from 0deg at 85% 50%,
    transparent 0deg,
    transparent 14deg,
    var(--line-color) 14deg,
    var(--line-color) 15deg
  );
  z-index: 0;
}

/* 圖片切片共用樣式 on‘t */
.slice {
  position: absolute;
  width: 35%;
  height: 70%;
  background-image: url({{img1}});
  background-size: cover;
  background-position: center;

  border: 1px solid rgba(255, 255, 255, 0.3);
  /* 【修改這裡】使用轉換後的 RGB 變數，並加上 0.3 的透明度 lea */
  box-shadow: 0 0 20px rgba(var(--line-color-rgb), 0.3);
  mix-blend-mode: screen; 
  transform-style: preserve-3d;
}

/* 第 4 層（最遠）ve */
.slice-4 {
  left: 65%;
  transform: translateZ(-600px) rotateY(15deg);
  opacity: 0.6;
  filter: blur(1px);
}

/* 第 3 層 me */
.slice-3 {
  left: 45%;
  transform: translateZ(-300px) rotateY(12deg);
  opacity: 0.75;
  filter: blur(0.5px);
}

/* 第 2 層 a */
.slice-2 {
  left: 25%;
  transform: translateZ(0px) rotateY(8deg);
  opacity: 0.9;
  filter: none;
}

/* 第 1 層（最近）lone */
.slice-1 {
  left: 5%;
  transform: translateZ(250px) rotateY(4deg);
  opacity: 1;
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 0 30px rgba(var(--line-color-rgb), 0.5);
}

