/*⁣⁠⁠⁠‍‍⁠‌‌⁠‍⁠⁠​‍​⁠​⁠⁠‌‌‌‌​‌‍⁠⁠⁠‌‍‍‌‌​‌‍‌⁠​‍⁠‌​‍​⁠‌⁠‌​‍​‍⁠‍‌​‍⁠‌‌⁠​⁣ 讓容器置中 */
.psp-wrapper {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
}

/* 鎖定圖片的原始比例 1920:1080 */
.psp-container {
  position: relative;
  aspect-ratio: 1920 / 1080;
  max-width: 100%;
  max-height: 100%;
}

.psp-img {
  width: 100%; height: 100%;
  display: block;
  object-fit: contain;
}

