.screen-area {
  position: absolute;
  left: 24.5%; top: 23%;
  width: 50.8%; height: 52%;
  border-radius: 2px;
  overflow: hidden;
}

.screen-bg {
  position: absolute;
  width: 100%; height: 100%;
  background-color: transparent;
  background-size: cover;
  background-position: center;
}

