.screen-ui {
  position: absolute;
  width: 100%; height: 100%;
  display: flex; flex-direction: column; justify-content: space-between;
  padding: 6px 10px;
  box-sizing: border-box;
  color: #ffffff;
  /* 乾淨的細陰影，防止背景太白時看不見字，但不會髒 */
